```ts
import { DEPARTEMENTS, type DeptId } from "../data/regulation";
const KEY = "carnet:prefs";
export interface Prefs { dept: DeptId; bigUI: boolean }
export const DEFAULT_PREFS: Prefs = { dept: "41", bigUI: false };
export function readPrefs(): Prefs {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return { ...DEFAULT_PREFS, bigUI: localStorage.getItem("bigUI") === "1" };
    const p = JSON.parse(raw) as Partial<Prefs>;
    return {
      dept: p.dept && p.dept in DEPARTEMENTS ? p.dept : DEFAULT_PREFS.dept,
      bigUI: p.bigUI === true,
    };
  } catch { return { ...DEFAULT_PREFS }; }
}
export function writePrefs(p: Prefs): void {
  try { localStorage.setItem(KEY, JSON.stringify(p)); } catch { /* private mode */ }
}
```
Le garde `p.dept in DEPARTEMENTS` est obligatoire : sans lui une valeur périmée ou bidouillée ferait afficher une réglementation inexistante.
